function fetch_approved_discounts(frm, row, callback) {
    // Don't overwrite existing discounts - initialize only once
    if (!frm.approved_discounts) {
        frm.approved_discounts = {};
    }

    // Validate required fields
    if (!row.item_code || !row.warehouse) {
        if (callback) {
            callback();
        }
        return;
    }

    var discounts = frm.approved_discounts;
    var key = row.item_code;

    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Approved Discounts",
            fieldname: [
                "expiry_date",
                "status",
                "item_name",
                "warehouse",
                "warehouse_type",
                "pricelist",
                "discount_rate",
                "min_qty"
            ],
            filters: {
                status: "Approved",
                item_name: row.item_code,
                warehouse: row.warehouse
            }
        },
        callback: function (response) {
            if (response.message) {
                var data = response.message;
                discounts[key] = {};

                // Manually assign each field
                if (data.expiry_date) { 
                    discounts[key].expiry_date = data.expiry_date; 
                }
                if (data.status) { 
                    discounts[key].status = data.status; 
                }
                if (data.item_name) { 
                    discounts[key].item_code = data.item_name; 
                }
                if (data.warehouse) { 
                    discounts[key].warehouse = data.warehouse; 
                }
                if (data.warehouse_type) { 
                    discounts[key].warehouse_type = data.warehouse_type; 
                }
                if (data.pricelist) { 
                    discounts[key].pricelist = data.pricelist; 
                }
                if (data.discount_rate) { 
                    discounts[key].discount_rate = data.discount_rate; 
                }
                if (data.min_qty) {
                    discounts[key].min_qty = data.min_qty;
                }

                console.log('✅ Discounts loaded for', key, discounts[key]);
            }

            // Call callback if provided
            if (callback) {
                callback();
            }
        },
        error: function(err) {
            console.error('Error fetching approved discounts:', err);
            if (callback) {
                callback();
            }
        }
    });
}

function recommended_rate(frm, row) {
    var item_code = row.item_code;
    var pricing = frm.promo_info_by_row[item_code];
    var discounts = frm.approved_discounts[item_code];

    // Validate that pricing data exists
    if (!pricing) {
        console.warn('No pricing data available for', item_code);
        return {
            rate: row.rate || 0,
            type: "unchanged"
        };
    }

    // Check if user is kagabuisa@gmail.com and return rate in form
    if (frappe.session.user === "kagabuisa@gmail.com" || frappe.session.user === "busingyesalama@gmail.com") {
        return {
            rate: row.rate,
            type: "unchanged"
        };
    }

    // Check if sales invoice is for damaged items
    if (frm.doc.customer === "Damaged Items CST") {
        return {
            rate: 0,
            type: "Damaged Item"
        };
    }

    // Check if item has a discount at set warehouse, for the items and set qty
    if (discounts && discounts.min_qty && discounts.discount_rate && discounts.min_qty <= row.qty) {
        console.log("we have a discount on this item");
        return {
            rate: discounts.discount_rate,
            type: "approved discount"
        };
    }

    // Check promo pricing
    if (pricing.promo_rate && pricing.promo_rate > 0 && pricing.promo_qty && pricing.promo_qty > 0 && row.qty >= pricing.promo_qty) {
        return {
            rate: pricing.promo_rate,
            type: "Promotion price"
        };
    }

    // Check carton pricing (if available)
    if (pricing.carton_price && pricing.carton_price > 0 && pricing.qty_per_carton && row.qty >= pricing.qty_per_carton) {
        console.log("item qty is above carton qty");
        return {
            rate: pricing.carton_price,
            type: "Carton price"
        };
    }

    // Use price list if qty does not qualify for a discount if item has a price_list_rate
    if (pricing.price_list_rate) {
        return {
            rate: pricing.price_list_rate,
            type: "Normal price"
        };
    }

    // Use computed rate if item is not on the selling price list
    var computedRate = 0;
    if (pricing.unit_cost) {
        computedRate = pricing.unit_cost * 1.3;
    }

    return {
        rate: computedRate,
        type: "the Computed rate (Get actual price from Accounts)"
    };
}

// Validate and correct the rate in a row
function validate_and_correct_rate_for_row(frm, row) {
    var rateResult = recommended_rate(frm, row);
    var minRate = rateResult.rate;
    var rateType = rateResult.type;

    var currentRate = row.rate;
    if (currentRate < minRate) {
        frappe.model.set_value(row.doctype, row.name, "rate", minRate);
        frappe.msgprint(__("\"" + row.item_code + "\" rate changed to " + minRate + " which is the minimum allowed for qty of " + row.qty + " at " + rateType));
    }
}

// Fetch pricing and item info for a specific row
function fetch_for_row(frm, row, callback) {
    if (!row.item_code) {
        if (callback) {
            callback();
        }
        return;
    }

    var item_code = row.item_code;

    var completedCalls = 0;
    var totalCalls = frm.doc.selling_price_list ? 2 : 1;

    function checkCompletion() {
        completedCalls = completedCalls + 1;
        if (completedCalls === totalCalls && callback) {
            callback();
        }
    }

    // Initialize promo_info_by_row if not already done
    if (!frm.promo_info_by_row) {
        frm.promo_info_by_row = {};
    }

    // Initialize item entry if not exists
    if (!frm.promo_info_by_row[item_code]) {
        frm.promo_info_by_row[item_code] = {};
    }

    var price_info = frm.promo_info_by_row[item_code];

    // Fetch Item Price record using get_value (since we expect one)
    if (frm.doc.selling_price_list) {
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Item Price",
                fieldname: [
                    "item_code",
                    "price_list_rate",
                    "promo_start_date",
                    "promo_expiry_date",
                    "promo_warehouse",
                    "promo_customer",
                    "warehouse_type",
                    "promo_rate",
                    "promo_qty",
                    "carton_price"
                ],
                filters: {
                    item_code: item_code,
                    price_list: frm.doc.selling_price_list
                }
            },
            callback: function (response) {
                if (response.message) {
                    var data = response.message;

                    // Manually assign each field
                    if (data.price_list_rate !== undefined) {
                        price_info.price_list_rate = data.price_list_rate;
                    }
                    if (data.promo_rate !== undefined) {
                        price_info.promo_rate = data.promo_rate;
                    }
                    if (data.promo_qty !== undefined) {
                        price_info.promo_qty = data.promo_qty;
                    }
                    if (data.carton_price !== undefined) {
                        price_info.carton_price = data.carton_price;
                    }
                    if (data.promo_start_date !== undefined) {
                        price_info.promo_start_date = data.promo_start_date;
                    }
                    if (data.promo_expiry_date !== undefined) {
                        price_info.promo_expiry_date = data.promo_expiry_date;
                    }
                    if (data.promo_warehouse !== undefined) {
                        price_info.promo_warehouse = data.promo_warehouse;
                    }
                    if (data.promo_customer !== undefined) {
                        price_info.promo_customer = data.promo_customer;
                    }
                    if (data.warehouse_type !== undefined) {
                        price_info.warehouse_type = data.warehouse_type;
                    }
                    if (data.item_code !== undefined) {
                        price_info.item_code = data.item_code;
                    }
                }
                checkCompletion();
            },
            error: function(err) {
                console.error('Error fetching item price:', err);
                checkCompletion();
            }
        });
    }

    // Fetch Item-specific fields: qty_per_carton and cost
    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Item",
            fieldname: ["qty_per_carton", "cost"],
            filters: { item_code: item_code }
        },
        callback: function (response) {
            if (response.message) {
                var itemData = response.message;
                if (itemData.qty_per_carton !== undefined) {
                    price_info.qty_per_carton = itemData.qty_per_carton;
                }
                if (itemData.cost !== undefined) {
                    price_info.unit_cost = itemData.cost;
                }
            }
            checkCompletion();
        },
        error: function(err) {
            console.error('Error fetching item data:', err);
            checkCompletion();
        }
    });
}

// Onload: fetch data for all items on sales invoice
frappe.ui.form.on("Sales Invoice", "onload", function (frm) {
    frm.promo_info_by_row = {};
    frm.approved_discounts = {};

    var items = frm.doc.items || [];
    for (var i = 0; i < items.length; i = i + 1) {
        var row = items[i];
        if (row.item_code) {
            fetch_for_row(frm, row);
            fetch_approved_discounts(frm, row);
        }
    }
});

// Clear and refetch all pricing data when price list changes
function refresh_all_pricing_data(frm) {
    // Clear existing pricing data
    frm.promo_info_by_row = {};

    var items = frm.doc.items || [];
    var itemsProcessed = 0;
    var totalItems = items.length;

    if (totalItems === 0) {
        frappe.msgprint(__("Pricing data refreshed for new price list"));
        return;
    }

    // Refetch data for all items
    for (var i = 0; i < items.length; i = i + 1) {
        var row = items[i];
        if (row.item_code) {
            fetch_for_row(frm, row, function () {
                itemsProcessed = itemsProcessed + 1;

                // Validate after fetching
                var currentRow = null;
                for (var j = 0; j < items.length; j = j + 1) {
                    if (items[j].item_code) {
                        currentRow = items[j];
                        validate_and_correct_rate_for_row(frm, currentRow);
                    }
                }

                // Show message only after all items processed
                if (itemsProcessed === totalItems) {
                    frappe.msgprint(__("Pricing data refreshed for new price list"));
                }
            });
        } else {
            itemsProcessed = itemsProcessed + 1;
        }
    }
}

// When item_code changes
frappe.ui.form.on("Sales Invoice Item", "item_code", function (frm, cdt, cdn) {
    var row = locals[cdt][cdn];
