// Final validation before saving
frappe.ui.form.on("Sales Invoice", "validate", function (frm) {
    var items = frm.doc.items || [];
    var rateCorrected = false;

    for (var i = 0; i < items.length; i = i + 1) {
        var row = items[i];

        // Get recommended rate
        var rateResult = recommended_rate(frm, row);
        var minRate = rateResult.rate;

        // Simple rate comparison
        if (row.rate < minRate) {
            frappe.model.set_value(row.doctype, row.name, "rate", minRate);
            rateCorrected = true;
        }
    }

    if (rateCorrected) {
        frappe.msgprint(__('Some rates were automatically corrected to meet minimum pricing'));
    }
});

